final class WooOrderMapper {
 public function map(\WC_Order $o):OrderExportData{$lines=[];foreach($o->get_items('line_item') as $i){$p=$i->get_product();if(!$p instanceof \WC_Product)continue;$lines[]=new OrderLineData(new ProductIdentifiers((string)$p->get_sku(),(string)$p->get_meta('_theobroma_1c_guid',true),(string)$p->get_meta('_theobroma_1c_article',true),(string)$p->get_meta('_theobroma_client_article',true),(string)$p->get_meta('_theobroma_ozon_product_id',true),(string)$p->get_meta('_theobroma_ozon_sku',true),(string)$p->get_meta('_theobroma_ean',true)),(string)$i->get_name(),(string)$i->get_quantity(),wc_format_decimal((string)$o->get_item_subtotal($i,false,false),2),wc_format_decimal((string)$i->get_total(),2),wc_format_decimal((string)max(0,(float)$i->get_subtotal()-(float)$i->get_total()),2));}$refunds=[];foreach($o->get_refunds() as $r)$refunds[]=new RefundData((int)$r->get_id(),$r->get_date_created()?->date('Y-m-d')??'',wc_format_decimal((string)abs((float)$r->get_total()),2));$fees=[];foreach($o->get_items('fee') as $fee)$fees[]=new ServiceLineData((string)$fee->get_id(),(string)$fee->get_name(),wc_format_decimal((string)((float)$fee->get_total()+(float)$fee->get_total_tax()),2));$created=$o->get_date_created();$paid=$o->get_date_paid();$shippingAddress=trim($o->get_shipping_address_1().' '.$o->get_shipping_address_2());$address=$shippingAddress!==''?$shippingAddress:trim($o->get_billing_address_1().' '.$o->get_billing_address_2());return new OrderExportData((int)$o->get_id(),(string)$o->get_order_number(),$created?->date('Y-m-d')??'', $created?->date('H:i:s')??'',(string)$o->get_currency(),wc_format_decimal((string)$o->get_total(),2),(string)$o->get_status(),$o->is_paid(),$o->has_status('cancelled'),$paid?->date(DATE_ATOM)??'',trim($o->get_formatted_billing_full_name()),(string)$o->get_billing_email(),(string)$o->get_billing_phone(),$address,(string)$o->get_payment_method_title(),wc_format_decimal((string)((int)$o->get_meta('_theobroma_bonus_spent_kopecks',true)/100),2),wc_format_decimal((string)((int)$o->get_meta('_theobroma_bonus_accrued_kopecks',true)/100),2),$lines,$refunds,$this->shippingName($o),wc_format_decimal((string)$o->get_shipping_total(),2),$o->get_coupon_codes(),$fees);}
 private function shippingName(\WC_Order $o):string{foreach($o->get_items('shipping') as $i)return(string)$i->get_name();return '';}
